        },
        {
          "@type": "Offer",
          "name": "Premium",
          "price": "19",
          "priceCurrency": "USD",
          "description": "12 AI signals per day for 30 days, unlimited charts and watchlist, priority support. No auto-renewal."
        }
      ]
    },
    {
      "@type": "FAQPage",
      "@id": "https://tradebise.com/#faq",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "What is Tradebise?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Tradebise is an AI-powered trading signals platform. It analyses live market data and produces buy, sell, or wait signals with an entry price, take-profit targets, and a stop-loss level. It covers cryptocurrency, forex, stocks, gold, and indices across 100+ markets."
          }
        },
        {
          "@type": "Question",
          "name": "How do I log in to Tradebise?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "You can log in at https://tradebise.com/login using your email and password, or with your Google account. To create a free account, go to https://tradebise.com/register."
          }
        },
        {
          "@type": "Question",
          "name": "Is Tradebise free?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. A free account includes 2 AI signals per day and unlimited chart views. Standard Premium costs 14.99 USD for 30 days and includes 12 signals per day, unlimited watchlist, and priority support. Premium + Signal Alerts (19.99 USD) adds new-signal alerts and target-hit results on Telegram. No plan auto-renews - you pay only when you choose to."
          }
        },
        {
          "@type": "Question",
          "name": "How do I buy Tradebise Premium?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Go to https://tradebise.com/premium, choose a plan and pay in USDT (BEP20, ERC20, or TRC20) - Standard Premium is 14.99 USD. Your plan is activated automatically once the blockchain confirms the payment, usually within a few minutes."
          }
        },
        {
          "@type": "Question",
          "name": "Which markets does Tradebise cover?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Tradebise covers cryptocurrency (BTC, ETH, SOL and thousands of pairs across Binance, Bybit, MEXC, OKX and Bitget), forex pairs, gold and silver (XAUUSD, XAGUSD), major stocks (AAPL, TSLA and others), and indices such as US30 and NAS100."
          }
        },
        {
          "@type": "Question",
          "name": "Are Tradebise signals financial advice?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. Tradebise signals are AI-generated technical analyses, not financial advice. Trading carries risk of capital loss. Always do your own research and never trade money you cannot afford to lose. Past performance does not guarantee future results."
          }
        }
      ]
    }
  ]
}
